treeTest("StyleValue, startEndBlank and ContainTextMark", inlineHtmlMod, () => {
  const m = inlineHtmlMod.mod!;
  for (const [s, want] of get<[string, string][]>("styleValue")) {
    assert.equal(m.StyleValue(s), want, `StyleValue ${JSON.stringify(s)}`);
  }
  for (const [s, a, b] of get<[string, string, string][]>("startEndBlank")) {
    assert.deepStrictEqual(m.startEndBlank(s), [a, b], `startEndBlank ${JSON.stringify(s)}`);
  }
  for (const [typ, q, want] of get<[string, string[], boolean][]>("containTextMark")) {
    const n = new ast.Node();
    n.TextMarkType = typ;
    assert.equal(m.ContainTextMark(n, ...q), want, `ContainTextMark ${JSON.stringify(typ)} ${JSON.stringify(q)}`);
  }
});

// ---- HTML text styles ----

const styleMod = await tryImport(() => import("./html_text_style.ts"));

function styleFrom(a: [string, string, string, number, string]) {
  const s = new styleMod.mod!.HTMLTextStyle();
  [s.Color, s.Background, s.Family, s.Size, s.SizeUnit] = a;
  return s;
}

function styleArr(s: { Color: string; Background: string; Family: string; Size: number; SizeUnit: string }): unknown[] {
  return [s.Color, s.Background, s.Family, s.Size, s.SizeUnit];
}

function domNode(tag: string, attrs: [string, string][]): html.Node {
  const n = new html.Node();
  n.Type = html.ElementNode;
  n.Data = tag;
  n.DataAtom = atom.Lookup(conv.BytesFromString(tag));
  for (const [k, v] of attrs) {
    const a = new html.Attribute();
    a.Key = k;
    a.Val = v;
    n.Attr.push(a);
  }
  return n;
}

treeTest("HTMLStyleDeclarations", styleMod, () => {
  const m = styleMod.mod!;
  const vs = get<[string, [string, string][]][]>("styleDecl");
  assert.ok(vs.length >= 300);
  for (const [style, want] of vs) {
    const got = m.HTMLStyleDeclarations(style);
    assert.deepStrictEqual([...got.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)), want, `style ${JSON.stringify(style)}`);
  }
});

treeTest("ResolveHTMLTextStyle and CSS", styleMod, () => {
  const m = styleMod.mod!;
  const vs = get<[string, [string, string][], [string, string, string, number, string], unknown[], string][]>("styleResolve");
  assert.ok(vs.length >= 300);
  for (const [tag, attrs, parent, want, css] of vs) {
    const got = m.ResolveHTMLTextStyle(domNode(tag, attrs), styleFrom(parent));
    const label = `${tag} ${JSON.stringify(attrs)} parent ${JSON.stringify(parent)}`;
    assert.deepStrictEqual(styleArr(got), want, label);
    assert.equal(got.CSS(), css, label);
  }
});

treeTest("HTMLTextStyle.CSS", styleMod, () => {
  for (const [arr, want] of get<[[string, string, string, number, string], string][]>("styleCSS")) {
    assert.equal(styleFrom(arr).CSS(), want, JSON.stringify(arr));
  }
});

treeTest("safeHTMLFontFamily", styleMod, () => {
  const m = styleMod.mod!;
  for (const [s, want] of get<[string, boolean][]>("fontFamily")) {
    assert.equal(m.safeHTMLFontFamily(s), want, JSON.stringify(s));
  }
});

treeTest("ApplyHTMLTextSemantics", styleMod, () => {
  const m = styleMod.mod!;
  for (const [chain, initial, want] of get<[string[], string, string][]>("styleSemantics")) {
    let dom: html.Node | null = null;
    for (const st of chain) {
      const n = domNode("span", [["style", st]]);
      n.Parent = dom;
      dom = n;
    }
    const node = new ast.Node(ast.NodeTextMark);
    node.TextMarkType = initial;
    m.ApplyHTMLTextSemantics(node, dom!);
    assert.equal(node.TextMarkType, want, `${JSON.stringify(chain)} ${JSON.stringify(initial)}`);
  }
});

treeTest("HTMLNodeTextStyle", styleMod, () => {
  const m = styleMod.mod!;
  for (const v of get<unknown[][]>("nodeTextStyle")) {
    const args = v[0] as [string, string][];
    if (v[1] === null) {
      assert.equal(args.length, 0);
      continue;
    }
    let dom: html.Node | null = null;
    for (const st of args) {
      const n = domNode(st[0], [["style", st[1]]]);
      n.Parent = dom;
      dom = n;
    }
    const got = m.HTMLNodeTextStyle(dom!);
    assert.deepStrictEqual([styleArr(got), got.CSS()], [v[1], v[2]], JSON.stringify(args));
  }
});

// ---- Port of parse/html_text_style_test.go ----

treeTest("ResolveHTMLTextStyle (html_text_style_test.go)", styleMod, () => {
  const m = styleMod.mod!;
  const mk = (color: string, background: string, family: string, size: number, unit: string) => styleFrom([color, background, family, size, unit]);
  const parent = mk("red", "", "Arial", 24, "px");
  const cases: [string, string, number, ReturnType<typeof mk>][] = [
    ["inherit", "", atom.Span, parent],
    ["small", "", atom.Small, mk("red", "", "Arial", 20, "px")],
    ["explicit small", "font-size:18px", atom.Small, mk("red", "", "Arial", 18, "px")],
    ["percentage", "font-size:50%", atom.Span, mk("red", "", "Arial", 12, "px")],
    ["em", "font-size:1.5em", atom.Span, mk("red", "", "Arial", 36, "px")],
    ["pt", "font-size:12pt", atom.Span, mk("red", "", "Arial", 16, "px")],
    ["priority", "COLOR: blue !important;color: green;background-color:currentColor", atom.Span, mk("blue", "blue", "Arial", 24, "px")],
    ["family", `font-family: 'Noto Sans', "Microsoft YaHei", sans-serif`, atom.Span, mk("red", "", `'Noto Sans', "Microsoft YaHei", sans-serif`, 24, "px")],
    ["unsafe", `color:url(https://example.com);background-color:expression(alert(1));font-family:"x";position:fixed;font-size:calc(1px + 2px)`, atom.Span, mk("red", "", `"x"`, 24, "px")],
  ];
  for (const [name, style, tag, want] of cases) {
    const n = new html.Node();
    n.DataAtom = tag;
    const a = new html.Attribute();
    a.Key = "style";
    a.Val = style;
    n.Attr = [a];
    const got = m.ResolveHTMLTextStyle(n, parent);
    assert.deepStrictEqual(got, want, name);
    assert.ok(!got.CSS().includes("position"), "layout style leaked");
  }
});

treeTest("HTMLStyleDeclarations (html_text_style_test.go)", styleMod, () => {
  const m = styleMod.mod!;
  const got = m.HTMLStyleDeclarations(`font-family:"A;B";color:rgb(1, 2, 3); COLOR:blue ! important;color:red;`);
  assert.equal(got.get("font-family"), `"A;B"`);
  assert.equal(got.get("color"), "blue");
});

treeTest("HTML background shorthand (html_text_style_test.go)", styleMod, () => {
  const m = styleMod.mod!;
  const cases: [string, string][] = [
    ["background-color:red;background:blue", "blue"],
    ["background:blue;background-color:red", "red"],
    ["background:blue!important;background-color:red", "blue"],
    ["background-color:red!important;background:blue", "red"],
    ["background:rgb(255,165,61)", "rgb(255,165,61)"],
    ["background:url(https://example.com/image.png)", ""],
  ];
  for (const [css, expected] of cases) {
    const n = new html.Node();
    const a = new html.Attribute();
    a.Key = "style";
    a.Val = css;
    n.Attr = [a];
    assert.equal(m.ResolveHTMLTextStyle(n, new m.HTMLTextStyle()).Background, expected, css);
  }
});

// ---- AddAutoLinkDomainSuffix: last, it changes the table ----

test("AddAutoLinkDomainSuffix", () => {
  const t = newTree();
  const a = get<{ probe: string[]; before: boolean[]; after: boolean[]; added: string[] }>("addSuffix");
  const http = conv.BytesFromString("http://");
  const run = () => a.probe.map((s) => t.isValidDomain(http, conv.BytesFromString("a." + s)));
  assert.deepStrictEqual(run(), a.before);
  for (const s of a.added) {
    autoLink.AddAutoLinkDomainSuffix(s);
  }
  assert.deepStrictEqual(run(), a.after);
});
